$levelTypeLabels=['basement'=>'Sótano','ground_floor'=>'Planta baja','floor'=>'Piso','mezzanine'=>'Mezzanina','technical_floor'=>'Piso técnico','terrace'=>'Terraza','roof'=>'Azotea'];
$compactRoute=static function(array $stops):string{
    if(!$stops)return 'Sin paradas';
    $segments=[];$i=0;$n=count($stops);
    while($i<$n){
        $name=trim((string)($stops[$i]['name']??''));
        $kind=null;$num=null;
        foreach([
            ['Elevado','/^Elevado\s+(\d+)$/iu'],
            ['Piso','/^Piso\s+(\d+)$/iu'],
            ['Sótano','/^S[oó]tano\s+S?(\d+)$/iu'],
        ] as [$label,$rx]){if(preg_match($rx,$name,$m)){$kind=$label;$num=(int)$m[1];break;}}
        if($kind===null){$segments[]=$name!==''?$name:'Parada';$i++;continue;}
        $start=$num;$end=$num;$j=$i+1;
        while($j<$n){$next=trim((string)($stops[$j]['name']??''));$m=[];$rx=$kind==='Elevado'?'/^Elevado\s+(\d+)$/iu':($kind==='Piso'?'/^Piso\s+(\d+)$/iu':'/^S[oó]tano\s+S?(\d+)$/iu');if(!preg_match($rx,$next,$m))break;$candidate=(int)$m[1];$step=$kind==='Sótano'?-1:1;if($candidate!==$end+$step)break;$end=$candidate;$j++;}
        if($start===$end)$segments[]=$kind.' '.$start;else $segments[]=$kind.' '.$start.'–'.$end;$i=$j;
    }
    return implode(' · ',$segments);
};
