k"></i><?php endif;?></a><?php endforeach;?></div></details><?php endif;?><?php if(!empty($meta['access_provider'])):?><small class="d-block mt-2 text-body-secondary">Proveedor previsto: <?=e($meta['access_provider'])?></small><?php endif;?></div><div class="card-footer d-flex justify-content-end gap-2"><?php if(can('properties.manage')):?><button class="btn btn-sm btn-outline-primary js-edit-vertical" data-bs-toggle="modal" data-bs-target="#verticalModal" data-json='<?=e(json_encode($json,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?>'><i class="bi bi-pencil"></i> Editar recorrido</button><?php endif;?><?php if(can('technical.delete')):?><form method="post" action="<?=url('vertical-transport-delete')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger" data-confirm="¿Eliminar este ascensor y sus paradas del modelo Property?"><i class="bi bi-trash"></i></button></form><?php endif;?></div></div></div>
