 endif;?></td><td><code><?=e($x['level_order']??0)?></code></td><td><label class="form-check m-0"><input class="form-check-input vertical-restricted-check" type="checkbox" name="restricted_stop_ids[]" value="<?=$x['id']?>"><span class="form-check-label small">Restringido</span></label></td></tr><?php endforeach;?></tbody></table></div></div>
