<script>
document.addEventListener('DOMContentLoaded',()=>{
  const modal=document.getElementById('verticalModal'),form=document.getElementById('verticalForm');
  const towerChecks=[...document.querySelectorAll('.vertical-tower-check')],rows=[...document.querySelectorAll('.vertical-stop-row')];
  const selectedTowerIds=()=>towerChecks.filter(x=>x.checked).map(x=>Number(x.value));
  const selectedBuildings=()=>[...new Set(towerChecks.filter(x=>x.checked).map(x=>Number(x.dataset.building||0)).filter(Boolean))];
  function filterStops(){const towers=selectedTowerIds(),buildings=selectedBuildings();let visible=0;rows.forEach(row=>{const tid=Number(row.dataset.tower||0),bid=Number(row.dataset.building||0),shared=row.dataset.shared==='1';const show=towers.length>0&&(tid?towers.includes(tid):(shared&&buildings.includes(bid)));row.hidden=!show;if(show)visible++;else{row.querySelector('.vertical-stop-check').checked=false;row.querySelector('.vertical-restricted-check').checked=false;}});document.getElementById('stopHelp').textContent=towers.length?`${visible} nivel(es) físicamente compatibles con la selección.`:'Selecciona una torre para ver sus niveles.';}
  towerChecks.forEach(x=>x.addEventListener('change',()=>{const buildings=selectedBuildings();if(buildings.length>1){x.checked=false;document.getElementById('verticalValidation').textContent='No puedes mezclar torres de edificios diferentes en un mismo ascensor.';}else document.getElementById('verticalValidation').textContent='';filterStops();}));
  const accessToggle=document.getElementById('verticalAccess');
  const syncRestrictedState=()=>rows.forEach(row=>{const r=row.querySelector('.vertical-restricted-check');r.disabled=!accessToggle.checked;if(r.disabled)r.checked=false;});
  rows.forEach(row=>{const stop=row.querySelector('.vertical-stop-check'),restricted=row.querySelector('.vertical-restricted-check');restricted.addEventListener('change',()=>{if(restricted.checked)stop.checked=true;});stop.addEventListener('change',()=>{if(!stop.checked)restricted.checked=false;});});accessToggle?.addEventListener('change',syncRestrictedState);
  document.getElementById('selectAllStops')?.addEventListener('click',()=>rows.filter(r=>!r.hidden).forEach(r=>r.querySelector('.vertical-stop-check').checked=true));
  document.getElementById('clearStops')?.addEventListener('click',()=>rows.forEach(r=>{r.querySelector('.vertical-stop-check').checked=false;r.querySelector('.vertical-restricted-check').checked=false;}));
  modal?.addEventListener('show.bs.modal',e=>{let d={};try{d=JSON.parse(e.relatedTarget?.dataset.json||'{}')}catch(x){}const m=d.metadata||{};document.getElementById('verticalTitle').textContent=d.id?'Editar ascensor':'Nuevo ascensor';for(const [id,key,def] of [['verticalId','id',''],['verticalCode','code',''],['verticalName','name',''],['verticalType','transport_type','passenger_elevator'],['verticalStatus','status','active']])document.getElementById(id).value=d[key]??def;document.getElementById('verticalUsage').value=m.usage||'';document.getElementById('verticalProvider').value=m.access_provider||'';document.getElementById('verticalNotes').value=m.notes||'';document.getElementById('verticalAccess').checked=!!m.access_control_enabled;syncRestrictedState();const towerIds=String(d.tower_ids||'').split(',').map(Number).filter(Boolean),stops=(d.stop_ids||[]).map(Number),restricted=(d.restricted_stop_ids||[]).map(Number);towerChecks.forEach(o=>o.checked=towerIds.includes(Number(o.value)));filterStops();rows.forEach(r=>{const id=Number(r.dataset.id);r.querySelector('.vertical-stop-check').checked=stops.includes(id)&&!r.hidden;r.querySelector('.vertical-restricted-check').checked=restricted.includes(id)&&!r.hidden;});document.getElementById('verticalValidation').textContent='';});
  form?.addEventListener('submit',e=>{const towers=selectedTowerIds(),stops=rows.filter(r=>!r.hidden&&r.querySelector('.vertical-stop-check').checked);if(!towers.length||!stops.length){e.preventDefault();document.getElementById('verticalValidation').textContent=!towers.length?'Selecciona la torre real del ascensor.':'Selecciona al menos una parada real.';}});
});
</script>
<?php endif;?>
